const state={rooms:2,baths:1,property:'apartment',type:'standard',lang:'uz'};
const prices={apartment:{base:99000,room:60000,bath:30000},house:{base:149000,room:72000,bath:35000},office:{base:199000,room:45000,bath:40000}};
const multipliers={standard:1,general:1.8,repair:2.65};
const fmt=n=>new Intl.NumberFormat('uz-UZ').format(Math.round(n/1000)*1000)+' so‘m';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function calculate(){const p=prices[state.property];const total=(p.base+state.rooms*p.room+state.baths*p.bath)*multipliers[state.type];$('#roomsValue').textContent=state.rooms;$('#bathsValue').textContent=state.baths;$('#totalPrice').textContent=fmt(total);return total}
$$('[data-action]').forEach(btn=>btn.addEventListener('click',()=>{const a=btn.dataset.action;if(a==='room-plus')state.rooms=Math.min(20,state.rooms+1);if(a==='room-minus')state.rooms=Math.max(1,state.rooms-1);if(a==='bath-plus')state.baths=Math.min(10,state.baths+1);if(a==='bath-minus')state.baths=Math.max(1,state.baths-1);calculate()}));
$$('[data-property]').forEach(btn=>btn.addEventListener('click',()=>{$$('[data-property]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');state.property=btn.dataset.property;calculate()}));
$$('[data-type]').forEach(btn=>btn.addEventListener('click',()=>{$$('[data-type]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');state.type=btn.dataset.type;calculate()}));
const modal=$('#orderModal');$('#orderButton').addEventListener('click',()=>{const property={apartment:'Kvartira',house:'Hovli',office:'Ofis'}[state.property];const type={standard:'Qo‘llab turuvchi',general:'General',repair:'Ta’mirdan keyin'}[state.type];$('#modalSummary').textContent=`${property} · ${state.rooms} xona · ${state.baths} sanuzel · ${type} · ${fmt(calculate())}`;modal.showModal()});$('.modal-close').addEventListener('click',()=>modal.close());
function success(e){e.preventDefault();if(modal.open)modal.close();$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);e.currentTarget.reset()}
$('#orderForm').addEventListener('submit',success);$('#businessForm').addEventListener('submit',success);
$('#menuButton').addEventListener('click',e=>{const open=$('#mainNav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});$$('.main-nav a').forEach(a=>a.addEventListener('click',()=>$('#mainNav').classList.remove('open')));
