const original={};$$('[data-i18n]').forEach(el=>original[el.dataset.i18n]=el.textContent);$('#langToggle').addEventListener('click',()=>{state.lang=state.lang==='uz'?'ru':'uz';document.documentElement.lang=state.lang;$('#langToggle').textContent=state.lang==='uz'?'RU':'UZ';$$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;el.textContent=state.lang==='ru'?(ru[key]||original[key]):original[key]})});
calculate();
